        file: File,
        witness: W,
        config: OriginalCircuitEvaluatedNextUseReceiptConfigV1,
        key: SigningKey,
        command_origin: CommandOrigin,
    ) -> Result<Self, Error> {
        let current = now()?;
        if matches!(&command_origin, CommandOrigin::FreshCreate) {
            config
                .selection
                .original_context()
                .require_new_original_receipt(current)?;
